-- Report ID : RPT_155
-- Report    : Receiver Aging PACA
-- Module    : Finance
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     sh.SHIPMENT                                          AS receipt_no,     sh.RECEIVE_DATE                                      AS receipt_date,     sh.INVC_MATCH_STATUS                                 AS invoice_match_status,     CASE sh.INVC_MATCH_STATUS         WHEN 'O' THEN 'Open - Awaiting Invoice Match'         WHEN 'C' THEN 'Closed'         WHEN 'M' THEN 'Matched'         ELSE sh.INVC_MATCH_STATUS     END                                                  AS match_status_desc,     oh.ORDER_NO                                          AS po_number,     oh.SUPPLIER                                          AS supplier_id,     sp.SUP_NAME                                          AS supplier_name,     sp.SUP_STATUS                                        AS supplier_status,     ol.LOCATION                                          AS location_id,     ol.LOC_TYPE                                          AS loc_type,     CASE ol.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                  AS location_name,     ss.ITEM                                              AS item_id,     im.ITEM_DESC                                         AS item_description,     im.DEPT                                              AS dept_no,     d.DEPT_NAME                                          AS dept_name,     CASE         WHEN im.DEPT IN (100, 101, 102)               THEN 'Y'         ELSE 'N'     END                                                  AS paca_eligible_ind,     ss.QTY_RECEIVED                                      AS qty_received,     ss.UNIT_COST                                         AS unit_cost,     ROUND(ss.QTY_RECEIVED * ss.UNIT_COST, 2)            AS receipt_cost_value,      ih.INVC_ID                                           AS invoice_id,     ih.INVC_DATE                                         AS invoice_date,     ih.TOTAL_MERCH_COST                                  AS invoice_amount,      sh.RECEIVE_DATE + 10                                AS paca_payment_due_date,      TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE)             AS days_since_receipt,      GREATEST(         TRUNC(SYSDATE) - (TRUNC(sh.RECEIVE_DATE) + 10)     , 0)                                                  AS days_past_paca_due_date,      CASE         WHEN TRUNC(SYSDATE) <= TRUNC(sh.RECEIVE_DATE) + 10             THEN 'WITHIN TERMS'         WHEN TRUNC(SYSDATE) - (TRUNC(sh.RECEIVE_DATE) + 10)              BETWEEN 1 AND 5             THEN 'PAST DUE - 1-5 DAYS'         WHEN TRUNC(SYSDATE) - (TRUNC(sh.RECEIVE_DATE) + 10)              BETWEEN 6 AND 15             THEN 'PAST DUE - 6-15 DAYS'         ELSE 'PAST DUE - 15+ DAYS - TRUST RIGHT RISK'     END                                                  AS paca_compliance_status,      CASE         WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 0  AND 7              THEN '0 - 7 Days'         WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 8  AND 15              THEN '8 - 15 Days'         WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 16 AND 30              THEN '16 - 30 Days'         ELSE '30+ Days'     END                                                  AS standard_aging_bucket,      TRUNC(SYSDATE)                                       AS report_date  FROM     MFCS_RDS.RDS_WV_SHIPMENT             sh     JOIN  MFCS_RDS.RDS_WV_SHIPSKU         ss   ON  sh.SHIPMENT       = ss.SHIPMENT     JOIN  MFCS_RDS.RDS_WV_ORDHEAD         oh   ON  sh.ORDER_NO       = oh.ORDER_NO     JOIN  MFCS_RDS.RDS_WV_ORDLOC          ol   ON  oh.ORDER_NO       = ol.ORDER_NO                                               AND  ss.ITEM            = ol.ITEM                                               AND  sh.TO_LOC          = ol.LOCATION     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER     im   ON  ss.ITEM            = im.ITEM     JOIN  MFCS_RDS.RDS_WV_DEPS            d    ON  im.DEPT            = d.DEPT     LEFT JOIN MFCS_RDS.RDS_WV_SUPS         sp  ON  oh.SUPPLIER        = sp.SUPPLIER     LEFT JOIN MFCS_RDS.RDS_WV_STORE        st  ON  ol.LOCATION        = st.STORE                                               AND  ol.LOC_TYPE         = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH          wh   ON  ol.LOCATION        = wh.WH                                               AND  ol.LOC_TYPE         = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_INVC_HEAD    ih  ON  oh.SUPPLIER        = ih.SUPPLIER  WHERE     sh.INVC_MATCH_STATUS != 'C'     AND sh.RECEIVE_DATE >= ADD_MONTHS(SYSDATE, -3)   ORDER BY     CASE         WHEN TRUNC(SYSDATE) - (TRUNC(sh.RECEIVE_DATE) + 10) > 15              AND im.DEPT IN (100, 101, 102)             THEN 1         WHEN TRUNC(SYSDATE) - (TRUNC(sh.RECEIVE_DATE) + 10) > 0              AND im.DEPT IN (100, 101, 102)             THEN 2         ELSE 3     END,     sh.RECEIVE_DATE,     sp.SUP_NAME,     sh.SHIPMENT